from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        dp = {}
        ans = nums[0]

        for x in nums:
            if x < 0:
                best_with_x_removed = dp.get(x, 0)
                best_with_x_kept = max(dp.values(), default=0) + x
                dp[x] = max(best_with_x_removed, best_with_x_kept, 0)
            else:
                for key in list(dp.keys()):
                    dp[key] += x
                if not dp:
                    dp[0] = 0
                ans = max(ans, max(dp.values()) + x)

            ans = max(ans, x)

        return ans
